/*
 * fsbench.c -- FSBENCH.NCP, the layer-by-layer SD read bench of TASK/FS08.
 *
 * A measuring tool, not product code. It runs from C:\AUTO\ BEFORE the AES
 * and the desktop exist (no GUI, no mouse, no accessories in the path) and
 * reads -- never writes -- a fixed test set on the SECOND partition, so
 * nothing on C: can be harmed:
 *
 *   D:\FSBENCH\  3 x 10 KiB, 3 x 100 KiB, 2 x 1 MiB, 2 x 10 MiB
 *                generated by sdk/examples/fsbench/gen-fsbench-files.py;
 *                names, sizes and CRC-32s are embedded (fsbench-manifest.h).
 *
 * Each layer of the path card -> program is timed on its own, bottom-up:
 *
 *   L1 BIOS   Lrwabs(0 = read, buf, n, sector, 3 = D:)  -- logical, through
 *             no GEMDOS, no FAT, no cache. A contiguous run of sectors from
 *             D:'s first data sector, the byte size of each file class, once
 *             with 1 sector per call and once with 128 sectors per call.
 *             docs/api/bios/04-rwabs.md, 07-getbpb.md.
 *   L2 GEMDOS per file: Fsfirst; then four rounds of Fopen / Fread loop /
 *             Fclose with 512 B, 4 KiB, 64 KiB and one whole-file Fread.
 *   L3 stdio  per file: fopen("rb") / fread(buf, 1, 1024) loop / fclose --
 *             the zView pattern (mintlib stdio; the stream buffer is
 *             st_blksize: 1024 = BUFSIZ until FS08 part 4, 32 KiB since,
 *             sdk/libc/newtos-arch/do_fstat.c). The page shows the value
 *             fstat() reports for the first file, read after its timed
 *             fread loop.
 *
 * Every Fread / fread lands in one file-sized buffer at the running offset,
 * so the CRC-32 is computed AFTER the timed region, not inside it.
 *
 * Whole sweep L1, L2, L3 twice: pass 1 "cold" (first after boot), pass 2
 * "warm". Nothing is printed or written to disk while a region is timed;
 * the log on C: is written only after both passes (it would otherwise share
 * the GEMDOS sector cache with D:).
 *
 * Clock: the ARM generic counter is NOT readable at EL0 -- the kernel never
 * sets CNTKCTL_EL1 (grep kernel/src), so CNTVCT_EL0 would trap. The clock is
 * therefore _hz_200 (5 ms; the kernel's tick handler credits ticks lost while
 * a long SVC ran with IRQs masked, kernel/src/drivers/timer.rs handle_irq),
 * refined: each timed region starts on a tick edge, and after it a spin loop
 * counts to the next edge; with L = spin iterations per full tick
 * (calibrated at start) the elapsed time is
 *     (t1 - t0 + 1) * 5 ms  -  remaining_spins / L * 5 ms.
 *
 * Output: four screen pages (Cconws) with a key wait between them, and the
 * same text appended to C:\FSBENCH.LOG. The key waits are skipped when
 * C:\FSBNOKEY.FLG exists or argv[1] is "-n" (headless QEMU runs: the IKBD
 * injector does not run during Cconin); each page then stays 3 s instead.
 *
 * Build: sdk/examples/fsbench/build-fsbench.sh (links sdk/libc/libc.a).
 */
#include <mint/osbind.h>
#include <mint/mintbind.h>
#include <mint/sysvars.h>
#include <stdarg.h>
#include <stdio.h>
#include <string.h>
#include <sys/stat.h>

#include "fsbench-manifest.h"

#define DRV_D        3                 /* BIOS drive number of D: */
#define DIR_D        "D:\\FSBENCH\\"
#define LOG_PATH     "C:\\FSBENCH.LOG"
#define NOKEY_PATH   "C:\\FSBNOKEY.FLG"
#define TICK_NS      5000000UL         /* one _hz_200 tick */
#define SPIN_LIMIT   (1UL << 34)       /* "_hz_200 is not running" */
#define RW_SECT      512               /* NewTOS Rwabs unit: tos-api/src/bios/mod.rs SECTOR */
#define L1_BIG       128               /* sectors per call, big-call mode */
#define S_NEWTOS_CPUCLOCK 2000         /* docs/api/gemdos/154-ssystem.md */

/* ------------------------------------------------------------------ clock */

static unsigned long spinL, spinLmin, spinLmax;  /* spin iterations per full tick */
static unsigned long nullmin, nullmax;           /* tstart();tstop() with nothing between */
static unsigned int t0tick;
static int clock_dead;

static unsigned int hz(void)
{
	return (unsigned int)get_sysvar(_hz_200);
}

/* Spin until _hz_200 leaves `t`; returns the iterations, stores the new value. */
static unsigned long spin_edge(unsigned int t, unsigned int *now)
{
	unsigned long n = 0;
	unsigned int v;

	while ((v = hz()) == t) {
		if (++n > SPIN_LIMIT) {
			clock_dead = 1;
			break;
		}
	}
	*now = v;
	return n;
}

static void tstart(void)
{
	unsigned int v;

	spin_edge(hz(), &v);
	t0tick = v;
}

/* Elapsed nanoseconds since the matching tstart(). */
static unsigned long tstop(void)
{
	unsigned int t1 = hz(), v;
	unsigned long n = spin_edge(t1, &v), rem;

	if (n > spinL)
		n = spinL;
	rem = spinL ? n * TICK_NS / spinL : 0;
	return (unsigned long)(t1 - t0tick + 1) * TICK_NS - rem;
}

static void calibrate(void)
{
	unsigned int v;
	unsigned long n;
	int i;

	unsigned long c[9], t;
	int j;

	/* L = median of 9 full ticks */
	spin_edge(hz(), &v);              /* align to an edge */
	for (i = 0; i < 9 && !clock_dead; i++)
		c[i] = spin_edge(v, &v);
	if (clock_dead)
		return;
	for (i = 1; i < 9; i++)
		for (j = i; j > 0 && c[j - 1] > c[j]; j--) {
			t = c[j];
			c[j] = c[j - 1];
			c[j - 1] = t;
		}
	spinLmin = c[0];
	spinL = c[4];
	spinLmax = c[8];

	/* the clock's own error bar: 16 empty measurements */
	nullmin = ~0UL;
	nullmax = 0;
	for (i = 0; i < 16; i++) {
		tstart();
		n = tstop();
		if (n < nullmin)
			nullmin = n;
		if (n > nullmax)
			nullmax = n;
	}
}

/* ------------------------------------------------------------------ CRC-32 */

static unsigned int crctab[256];

static void crc_init(void)
{
	unsigned int c, n, k;

	for (n = 0; n < 256; n++) {
		c = n;
		for (k = 0; k < 8; k++)
			c = (c & 1) ? 0xEDB88320u ^ (c >> 1) : c >> 1;
		crctab[n] = c;
	}
}

static unsigned int crc32(const unsigned char *p, long len)
{
	unsigned int c = 0xFFFFFFFFu;

	while (len-- > 0)
		c = crctab[(c ^ *p++) & 0xFF] ^ (c >> 8);
	return c ^ 0xFFFFFFFFu;
}

/* ------------------------------------------------------------------ output */

#define NPAGES 4
#define PAGESZ 8192
static char page[NPAGES][PAGESZ];
static int pagelen[NPAGES];

static void pg(int p, const char *fmt, ...)
{
	va_list ap;
	int n;

	va_start(ap, fmt);
	n = vsnprintf(page[p] + pagelen[p], PAGESZ - pagelen[p], fmt, ap);
	va_end(ap);
	if (n > 0)
		pagelen[p] += n < PAGESZ - pagelen[p] ? n : PAGESZ - 1 - pagelen[p];
}

static void progress(const char *fmt, ...)
{
	char line[128];
	va_list ap;

	va_start(ap, fmt);
	vsnprintf(line, sizeof line, fmt, ap);
	va_end(ap);
	Cconws(line);
}

/* ms with 4-5 significant digits, right-aligned in `w` columns */
static const char *ms(char *buf, int w, unsigned long ns)
{
	char t[24];
	unsigned long us = ns / 1000;

	if (us < 10000)
		sprintf(t, "%lu.%03lu", us / 1000, us % 1000);
	else if (us < 100000)
		sprintf(t, "%lu.%02lu", us / 1000, (us % 1000) / 10);
	else if (us < 1000000)
		sprintf(t, "%lu.%01lu", us / 1000, (us % 1000) / 100);
	else
		sprintf(t, "%lu", us / 1000);
	sprintf(buf, "%*s", w, t);
	return buf;
}

static unsigned long kbs(long bytes, unsigned long ns)
{
	return ns ? (unsigned long)bytes * 1000000000UL / 1024UL / ns : 0;
}

/* ------------------------------------------------------------------ results */

static const long l1bytes[4] = { 10240L, 102400L, 1048576L, 10485760L };
static const char *const l1name[4] = { "10K", "100K", "1M", "10M" };
static const int l1spc[2] = { 1, L1_BIG };

struct l1r { long calls; unsigned long ns; long err; };
static struct l1r L1[2][4][2];          /* [pass][class][mode] */

static const long chunk[4] = { 512L, 4096L, 65536L, 0L };   /* 0 = whole file */

struct l2r {
	long sferr, len;                 /* Fsfirst result, DTA length */
	unsigned long ns_sf;
	unsigned long ns_op[4], ns_rd[4], ns_cl[4];
	long calls[4], got[4], err[4];
	int crcok[4];
};
static struct l2r L2[2][FSB_NFILES];

struct l3r {
	int open_ok;
	unsigned long ns_op, ns_rd, ns_cl;
	long calls, got;
	int crcok;
};
static struct l3r L3[2][FSB_NFILES];
static long l3_blksize = -1;	/* fstat st_blksize of the first L3 file */

static unsigned char *buf;
static long bufsz;
static unsigned long l1start, l1total;   /* 512-byte units */
static int l1ok;
static const void *bpbp;

/* ------------------------------------------------------------------ L1 */

static void run_l1(int pass)
{
	int c, m;
	unsigned long s, k, nsec;
	long r;

	if (!l1ok)
		return;
	for (c = 0; c < 4; c++) {
		nsec = l1bytes[c] / RW_SECT;
		for (m = 0; m < 2; m++) {
			struct l1r *x = &L1[pass][c][m];
			progress("L1 %s Rwabs %-4s %3d sec/call\r\n",
				 pass ? "warm" : "cold", l1name[c], l1spc[m]);
			if (l1start + nsec > l1total) {
				x->err = 1;      /* D: too small for this class */
				continue;
			}
			x->calls = 0;
			x->err = 0;
			tstart();
			for (s = 0; s < nsec; s += k) {
				k = nsec - s < (unsigned long)l1spc[m] ? nsec - s : (unsigned long)l1spc[m];
				r = Lrwabs(0, buf, (short)k, (long)(l1start + s), DRV_D);
				x->calls++;
				if (r < 0) {
					x->err = r;
					break;
				}
			}
			x->ns = tstop();
		}
	}
}

/* ------------------------------------------------------------------ L2 */

static unsigned char dta[64];

static void path_of(char *p, int f)
{
	strcpy(p, DIR_D);
	strcat(p, fsb_files[f].name);
}

static void run_l2(int pass)
{
	char path[64];
	int f, k;
	long h, n, want, total, sz;

	Fsetdta(dta);
	for (f = 0; f < FSB_NFILES; f++) {
		struct l2r *x = &L2[pass][f];
		path_of(path, f);
		progress("L2 %s %s\r\n", pass ? "warm" : "cold", fsb_files[f].name);
		tstart();
		x->sferr = Fsfirst(path, 0);
		x->ns_sf = tstop();
		if (x->sferr < 0)
			continue;
		/* d_length at DTA offset 26, native (little-endian) order
		 * (tos-api/src/bdos/fs/find.rs makbuf) */
		x->len = (long)((unsigned int)dta[26] | (unsigned int)dta[27] << 8 |
				(unsigned int)dta[28] << 16 | (unsigned int)dta[29] << 24);
		sz = fsb_files[f].size;
		if (x->len != sz)
			continue;
		for (k = 0; k < 4; k++) {
			want = chunk[k] ? chunk[k] : sz;
			tstart();
			h = Fopen(path, 0);
			x->ns_op[k] = tstop();
			if (h < 0) {
				x->err[k] = h;
				continue;
			}
			total = 0;
			x->calls[k] = 0;
			tstart();
			for (;;) {
				n = Fread((short)h, want, buf + total);
				x->calls[k]++;
				if (n <= 0) {
					if (n < 0)
						x->err[k] = n;
					break;
				}
				total += n;
				if (n < want || total >= sz)
					break;
			}
			x->ns_rd[k] = tstop();
			tstart();
			Fclose((short)h);
			x->ns_cl[k] = tstop();
			x->got[k] = total;
			x->crcok[k] = total == sz && crc32(buf, total) == fsb_files[f].crc;
		}
	}
}

/* ------------------------------------------------------------------ L3 */

static void run_l3(int pass)
{
	char path[64];
	int f;
	FILE *fp;
	size_t n;
	long total, sz;

	for (f = 0; f < FSB_NFILES; f++) {
		struct l3r *x = &L3[pass][f];
		path_of(path, f);
		sz = fsb_files[f].size;
		progress("L3 %s %s\r\n", pass ? "warm" : "cold", fsb_files[f].name);
		tstart();
		fp = fopen(path, "rb");
		x->ns_op = tstop();
		if (!fp)
			continue;
		x->open_ok = 1;
		total = 0;
		x->calls = 0;
		tstart();
		for (;;) {
			if (total + 1024 > bufsz)
				break;
			n = fread(buf + total, 1, 1024, fp);
			x->calls++;
			total += (long)n;
			if (n < 1024)
				break;
		}
		x->ns_rd = tstop();
		if (l3_blksize < 0) {
			/* outside every timed region: the buffer size stdio chose */
			struct stat st;
			if (fstat(fileno(fp), &st) == 0)
				l3_blksize = (long)st.st_blksize;
		}
		tstart();
		fclose(fp);
		x->ns_cl = tstop();
		x->got = total;
		x->crcok = total == sz && crc32(buf, total) == fsb_files[f].crc;
	}
}

/* ------------------------------------------------------------------ report */

static int crc_good, crc_bad, missing;

static void report_header(void)
{
	long sv = Sversion();
	unsigned long sb = (unsigned long)get_sysvar(_sysbase);
	unsigned short osver = 0;
	unsigned int osdate = 0;
	int cpu = 0;
	long cr;
	char m1[16], m2[16];

	if (sb) {
		memcpy(&osver, (const void *)(sb + 0x02), 2);
		memcpy(&osdate, (const void *)(sb + 0x18), 4);
	}
	cr = Ssystem(S_NEWTOS_CPUCLOCK, (long)&cpu, 0);
	pg(0, "==== FSBENCH (TASK/FS08) -- read path, layer by layer, D:\\FSBENCH ====\r\n");
	pg(0, "kernel: GEMDOS Sversion %04lx, OSHEADER os_version %x.%02x os_date %08x\r\n",
	   sv & 0xFFFF, osver >> 8, osver & 0xFF, osdate);
	if (cr < 0)
		pg(0, "        CPU clock n/a (Ssystem %ld); build rev: boot screen only\r\n", cr);
	else
		pg(0, "        CPU clock %d MHz; build rev: boot screen only\r\n", cpu / 1000000);
	pg(0, "clock: _hz_200 5 ms, edge sync + spin interpolation (CNTVCT_EL0 off at EL0)\r\n");
	pg(0, "       spins/tick %lu (%lu..%lu), empty measurement %s..%s ms\r\n",
	   spinL, spinLmin, spinLmax, ms(m1, 1, nullmin), ms(m2, 1, nullmax));
}

static void report_l1(void)
{
	const unsigned short *b = bpbp;
	char m1[16];
	int p, c, m;

	if (!bpbp) {
		pg(0, "L1 BIOS: Getbpb(D:) = 0 -- no D: or not FAT12/16; L1 skipped\r\n");
		return;
	}
	pg(0, "D: BPB recsiz %u clsiz %u clsizb %u datrec %u numcl %u flags %u\r\n",
	   b[0], b[1], b[2], b[6], b[7], b[8]);
	if (!l1ok) {
		pg(0, "L1 BIOS: BPB has recsiz or clsiz 0 -- L1 skipped\r\n");
		return;
	}
	if (b[0] != RW_SECT)
		pg(0, "  note: recsiz != 512; NewTOS Rwabs moves 512-byte sectors regardless\r\n");
	pg(0, "L1 BIOS Lrwabs(read, D:) from sector %lu (512 B units, no GEMDOS/FAT/cache)\r\n",
	   l1start);
	pg(0, "class      bytes pass  sec/call  calls         ms    KB/s   ms/call\r\n");
	for (p = 0; p < 2; p++)
		for (c = 0; c < 4; c++)
			for (m = 0; m < 2; m++) {
				struct l1r *x = &L1[p][c][m];
				char m2[16];
				if (x->err > 0) {
					pg(0, "%-5s %10ld %-4s  %8d  D: too small\r\n",
					   l1name[c], l1bytes[c], p ? "warm" : "cold", l1spc[m]);
					continue;
				}
				pg(0, "%-5s %10ld %-4s  %8d %6ld %s %7lu %s%s\r\n",
				   l1name[c], l1bytes[c], p ? "warm" : "cold", l1spc[m], x->calls,
				   ms(m1, 10, x->ns), kbs(l1bytes[c], x->ns),
				   ms(m2, 9, x->calls ? x->ns / x->calls : 0),
				   x->err ? "  ERR" : "");
				if (x->err)
					pg(0, "      Rwabs error %ld after %ld calls\r\n", x->err, x->calls);
			}
}

static void report_l2(int p)
{
	char a[16], b[16], c[16], r[4][16];
	int f, k, ok;
	int pgn = 1 + p;

	pg(pgn, "L2 GEMDOS %s  (ms; Fopen/Fclose of the 512 B round; KB/s below)\r\n",
	   p ? "warm" : "cold");
	pg(pgn, "file          size Fsfirst  Fopen Fclose |   512 B    4 KB   64 KB   whole crc\r\n");
	for (f = 0; f < FSB_NFILES; f++) {
		struct l2r *x = &L2[p][f];
		long sz = fsb_files[f].size;
		if (x->sferr < 0) {
			pg(pgn, "%-10s %9ld MISSING (Fsfirst %ld)\r\n", fsb_files[f].name, sz, x->sferr);
			missing++;
			continue;
		}
		if (x->len != sz) {
			pg(pgn, "%-10s %9ld WRONG SIZE %ld (manifest %ld) -- not read\r\n",
			   fsb_files[f].name, sz, x->len, sz);
			crc_bad++;
			continue;
		}
		ok = 1;
		for (k = 0; k < 4; k++) {
			ms(r[k], 8, x->ns_rd[k]);
			if (x->err[k] || !x->crcok[k])
				ok = 0;
			if (x->crcok[k])
				crc_good++;
			else
				crc_bad++;
		}
		pg(pgn, "%-10s %8ld %s %s %s |%s%s%s%s %s\r\n", fsb_files[f].name, sz,
		   ms(a, 7, x->ns_sf), ms(b, 6, x->ns_op[0]), ms(c, 6, x->ns_cl[0]),
		   r[0], r[1], r[2], r[3], ok ? "ok" : "BAD");
		pg(pgn, "%36s KB/s |%8lu%8lu%8lu%8lu\r\n", "",
		   kbs(sz, x->ns_rd[0]), kbs(sz, x->ns_rd[1]),
		   kbs(sz, x->ns_rd[2]), kbs(sz, x->ns_rd[3]));
	}
}

static void report_l2_detail(char *out, int outsz)
{
	char a[16], b[16], c[16];
	int p, f, k, n = 0;

	n += snprintf(out + n, outsz - n,
		      "# L2 detail: pass file chunk Fopen Fread Fclose (ms) Freads bytes err crc\r\n");
	for (p = 0; p < 2; p++)
		for (f = 0; f < FSB_NFILES; f++) {
			struct l2r *x = &L2[p][f];
			if (x->sferr < 0 || x->len != fsb_files[f].size)
				continue;
			for (k = 0; k < 4 && n < outsz - 160; k++)
				n += snprintf(out + n, outsz - n,
					      "# %s %-10s %8ld %s %s %s %6ld %9ld %ld %s\r\n",
					      p ? "warm" : "cold", fsb_files[f].name,
					      chunk[k] ? chunk[k] : fsb_files[f].size,
					      ms(a, 8, x->ns_op[k]), ms(b, 9, x->ns_rd[k]),
					      ms(c, 8, x->ns_cl[k]), x->calls[k], x->got[k],
					      x->err[k], x->crcok[k] ? "ok" : "BAD");
		}
}

static void report_l3(void)
{
	char a[16], b[16], c[16];
	int p, f;

	pg(3, "L3 stdio fopen(rb) / fread(buf,1,1024) / fclose  (ms; st_blksize %ld)\r\n",
	   l3_blksize);
	pg(3, "file           size pass   fopen     fread    KB/s freads fclose  crc\r\n");
	for (p = 0; p < 2; p++)
		for (f = 0; f < FSB_NFILES; f++) {
			struct l3r *x = &L3[p][f];
			long sz = fsb_files[f].size;
			if (!x->open_ok) {
				pg(3, "%-10s %9ld %-4s fopen failed\r\n", fsb_files[f].name, sz,
				   p ? "warm" : "cold");
				missing++;
				continue;
			}
			if (x->crcok)
				crc_good++;
			else
				crc_bad++;
			pg(3, "%-10s %9ld %-4s %s %s %7lu %6ld %s  %s\r\n", fsb_files[f].name, sz,
			   p ? "warm" : "cold", ms(a, 7, x->ns_op), ms(b, 9, x->ns_rd),
			   kbs(sz, x->ns_rd), x->calls, ms(c, 6, x->ns_cl),
			   x->crcok ? "ok" : "BAD");
		}
}

/* ------------------------------------------------------------------ main */

static char detail[16384];

static void keywait(int nokey, const char *what)
{
	if (nokey) {
		/* headless: a 3 s pause instead, long enough for a screendump */
		unsigned int t = hz();
		Cconws("(no key wait: C:\\FSBNOKEY.FLG / -n; 3 s pause)\r\n");
		while (hz() - t < 600)
			;
		return;
	}
	Cconws("-- photo, then press a key for ");
	Cconws(what);
	Cconws(" --\r\n");
	Cconin();
}

int main(int argc, char **argv)
{
	int p, nokey = 0;
	long h, maxsz = 0;
	int f;

	Cconws("\r\nFSBENCH (FS08): calibrating clock...\r\n");
	crc_init();
	calibrate();
	if (clock_dead || spinL == 0) {
		Cconws("FSBENCH: _hz_200 is not counting -- cannot time anything, abort.\r\n");
		return 1;
	}

	for (f = 0; f < FSB_NFILES; f++)
		if (fsb_files[f].size > maxsz)
			maxsz = fsb_files[f].size;
	bufsz = maxsz + 65536L;
	buf = (unsigned char *)Malloc(bufsz);
	if ((long)buf <= 0) {
		Cconws("FSBENCH: Malloc of the read buffer failed, abort.\r\n");
		return 1;
	}

	/* D:'s geometry. Getbpb is a BIOS read of D:'s boot sector, done once
	 * before pass 1 -- it does not touch the GEMDOS cache. */
	bpbp = (const void *)Getbpb(DRV_D);
	if (bpbp) {
		const unsigned short *b = bpbp;
		/* BPB words: recsiz clsiz clsizb rdlen fsiz fatrec datrec numcl flags */
		l1start = (unsigned long)b[6] * b[0] / RW_SECT;
		l1total = ((unsigned long)b[6] + (unsigned long)b[7] * b[1]) * b[0] / RW_SECT;
		l1ok = b[0] != 0 && b[1] != 0;
	}

	report_header();

	for (p = 0; p < 2; p++) {
		run_l1(p);
		run_l2(p);
		run_l3(p);
	}
	report_l1();
	report_l2(0);
	report_l2(1);
	report_l3();
	report_l2_detail(detail, sizeof detail);
	pg(3, "summary: %d reads crc ok, %d bad, %d missing/failed (L2+L3, both passes)\r\n",
	   crc_good, crc_bad, missing);
	pg(3, "==== FSBENCH end ====\r\n");

	/* Only now touch C:. */
	if (argc > 1 && strcmp(argv[1], "-n") == 0)
		nokey = 1;
	h = Fopen(NOKEY_PATH, 0);
	if (h >= 0) {
		Fclose((short)h);
		nokey = 1;
	}
	h = Fopen(LOG_PATH, 1);
	if (h >= 0)
		Fseek(0, (short)h, 2);
	else
		h = Fcreate(LOG_PATH, 0);
	if (h >= 0) {
		static const char sep[] = "\r\n";
		for (p = 0; p < NPAGES; p++)
			Fwrite((short)h, pagelen[p], page[p]);
		Fwrite((short)h, strlen(detail), detail);
		Fwrite((short)h, 2, sep);
		Fclose((short)h);
	}

	Cconws("\r\n");
	for (p = 0; p < NPAGES; p++) {
		Cconws(page[p]);
		keywait(nokey, p + 1 < NPAGES ? "the next page" : "the desktop");
	}
	if (h < 0)
		progress("FSBENCH: could not write %s (%ld)\r\n", LOG_PATH, h);
	else
		Cconws("FSBENCH: log appended to " LOG_PATH "\r\n");
	Mfree(buf);
	return 0;
}
